<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

/**
 * Isi harga (HET) sparepart dari master price list resmi (per Oktober 2026).
 *
 * Jalankan di production/cPanel dengan:
 *   php artisan db:seed --class=SparepartPriceSeeder
 *
 * Seeder ini idempotent: aman dijalankan berkali-kali. Data harga ditempel
 * di bawah (format: nama-price-list|slug-motor|part-number|harga), dan hanya
 * mengupdate kolom items.price milik sparepart yang part_number-nya cocok
 * dengan motor yang terdaftar pada price list tersebut.
 *
 * Catatan: price list 250-clx, draco, sm-master & sm3 sengaja TIDAK dimasukkan
 * karena tidak ada motor dengan nama tersebut di database.
 * Price list 450-clc, 450-clc-bobber & 450-sr sudah dipetakan ke motornya
 * (cfmoto-450-clc, cfmoto-clc-450-bobber, cfmoto-450-sr, 450sr-double-arm);
 * saat ini sparepart motor tersebut belum ada, sehingga otomatis dilewati
 * sampai katalog sparepartnya diimpor.
 */
class SparepartPriceSeeder extends Seeder
{
    /** slug motor (items.slug) => nama file master price list sumbernya */
    private const MAP = [
        'porter-125'          => 'porter',
        'gy-150-aries'        => 'gy-aries',
        'v16-plus'            => 'v16-plus',
        'papio-x0-1'          => 'papio-xo-1',
        'papio-x0-2'          => 'papio-xo-2',
        'cfmoto-250-sr-lite'  => '250-sr',
        'cfmoto-250-clc'      => '250-clc',
        'cfmoto-450-mt'       => '450-mt',
        'morbius'             => 'morbius',
        'greta'               => 'greta',
        'letbe-series-neon'   => 'letbe-neon',
        'velora-150'          => 'velora',
        'zeeho-ae6'           => 'zeeho-ae6',
        'zeeho-ae8'           => 'zeeho-ae8',
        'e-classic'           => 'e-classic',
        // berikut belum ada sparepart terhubung — otomatis dilewati:
        'cfmoto-450-clc'      => '450-clc',
        'cfmoto-clc-450-bobber' => '450-clc-bobber',
        'cfmoto-450-sr'       => '450-sr',
        '450sr-double-arm'    => '450-sr',
    ];

