    public function run(): void
    {
        $motorTypeId = DB::table('category_types')->where('slug', 'motor')->value('id');
        $sparepartTypeId = DB::table('category_types')->where('slug', 'sparepart')->value('id');

        if (! $motorTypeId || ! $sparepartTypeId) {
            $this->command?->error('category_types "motor"/"sparepart" tidak ditemukan.');

            return;
        }

        // price-list => slug-motor => [part_number => harga]
        $prices = [];
        foreach (preg_split('/\r\n|\r|\n/', self::DATA) as $line) {
            if ($line === '' || substr_count($line, '|') !== 3) {
                continue;
            }
            [$list, $motorSlug, $partNumber, $price] = explode('|', $line);
            $prices[$list][$motorSlug][trim($partNumber)] = (int) $price;
        }

        $motorIds = DB::table('items')
            ->where('category_type_id', $motorTypeId)
            ->whereIn('slug', array_keys(self::MAP))
            ->pluck('id', 'slug');

        $updated = 0;

        foreach (self::MAP as $motorSlug => $list) {
            $motorId = $motorIds[$motorSlug] ?? null;
            if (! $motorId) {
                $this->command?->warn("Motor \"{$motorSlug}\" tidak ada di database, dilewati.");

                continue;
            }

            $byPrice = [];
            $itemIds = DB::table('item_motor_compatibility')
                ->where('motor_id', $motorId)
                ->pluck('item_id')
                ->unique();

            if ($itemIds->isEmpty()) {
                $this->command?->warn("Motor \"{$motorSlug}\" belum punya sparepart terhubung, dilewati.");

                continue;
            }

            foreach (array_chunk($itemIds->all(), 500) as $chunk) {
                $items = DB::table('items')
                    ->whereIn('id', $chunk)
                    ->where('category_type_id', $sparepartTypeId)
                    ->whereNotNull('part_number')
                    ->get(['id', 'part_number']);

                foreach ($items as $item) {
                    $price = $prices[$list][$motorSlug][trim($item->part_number)] ?? null;
                    if ($price !== null && $price > 0) {
                        $byPrice[$price][] = $item->id;
                    }
                }
            }

            $count = 0;
            foreach ($byPrice as $price => $ids) {
                foreach (array_chunk($ids, 500) as $chunk) {
                    $count += DB::table('items')->whereIn('id', $chunk)->update(['price' => $price]);
                }
            }

            $updated += $count;
            $this->command?->info("{$motorSlug} ({$list}): {$count} sparepart diisi harga.");
        }

        $this->command?->info("Selesai. Total {$updated} sparepart memiliki harga.");
    }
}
